#!/usr/bin/env python3
"""
FastAPI Application for California Housing Price Prediction
"""

from fastapi import FastAPI
from fastapi.responses import JSONResponse
import pickle
import numpy as np

# Create FastAPI app
app = FastAPI(title="California Housing Price Prediction API")

# Global variable to store the loaded model
best_model = None
model_name = None
model_type = None

# Load model at startup
@app.on_event("startup")
def load_model():
    global best_model, model_name, model_type
    try:
        with open('/app/models/best_model.pkl', 'rb') as f:
            best_model = pickle.load(f)
        # Get model name and type from the model
        # For sklearn models, we can use the class name
        model_name = best_model.__class__.__name__
        # Map sklearn class names to user-friendly names
        if 'RandomForest' in model_name:
            model_type = 'RandomForestRegressor'
        elif 'Ridge' in model_name:
            model_type = 'Ridge'
        elif 'LinearRegression' in model_name:
            model_type = 'LinearRegression'
        else:
            model_type = model_name
        print(f"Model loaded: {model_name} ({model_type})")
    except Exception as e:
        print(f"Error loading model: {e}")
        best_model = None
        model_name = None
        model_type = None

@app.get("/health")
def health_check():
    """Health check endpoint"""
    return {
        "status": "healthy",
        "model_loaded": best_model is not None
    }

@app.get("/model-info")
def model_info():
    """Return model information"""
    if best_model is None:
        return JSONResponse(
            status_code=500,
            content={"error": "Model not loaded"}
        )
    return {
        "model_name": model_name,
        "model_type": model_type,
        "features_count": 8
    }

@app.post("/predict")
def predict(features: list):
    """
    Predict house price for a single sample.
    Input: {"features": [float, float, ...]} (8 floats)
    Output: {"prediction": float, "model_name": string}
    """
    if best_model is None:
        return JSONResponse(
            status_code=500,
            content={"error": "Model not loaded"}
        )

    # Validate input - must have exactly 8 features
    if len(features) != 8:
        return JSONResponse(
            status_code=400,
            content={"error": "Exactly 8 features required"}
        )

    # Convert to numpy array
    X = np.array(features).reshape(1, -1)

    # Make prediction
    prediction = float(best_model.predict(X)[0])

    return {
        "prediction": prediction,
        "model_name": model_name
    }

@app.post("/predict-batch")
def predict_batch(features_list: list):
    """
    Predict house prices for multiple samples.
    Input: {"features_list": [[float, ...], [float, ...], ...]}
    Output: {"predictions": [float, ...], "model_name": string, "count": int}
    """
    if best_model is None:
        return JSONResponse(
            status_code=500,
            content={"error": "Model not loaded"}
        )

    # Validate input
    if not isinstance(features_list, list):
        return JSONResponse(
            status_code=400,
            content={"error": "features_list must be a list"}
        )

    # Each inner array must have exactly 8 features
    for i, features in enumerate(features_list):
        if not isinstance(features, list):
            return JSONResponse(
                status_code=400,
                content={"error": f"Element {i} must be a list"}
            )
        if len(features) != 8:
            return JSONResponse(
                status_code=400,
                content={"error": f"Sample {i} must have exactly 8 features, got {len(features)}"}
            )

    # Convert to numpy array
    X = np.array(features_list)

    # Make predictions
    predictions = best_model.predict(X)
    predictions_list = [float(p) for p in predictions]

    return {
        "predictions": predictions_list,
        "model_name": model_name,
        "count": len(predictions_list)
    }

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
EOF"}

